sys_variable_value.value:
(function execute(inputs, outputs) {
    value_brl = parseFloat(inputs.value_brl);
    var rate =  parseFloat(inputs.rate_usd);

    var calculation = value_brl * rate;

    outputs.final_value_usd = calculation.toFixed(2).toString();
})(inputs, outputs);

